            "name": "run_sql",
            "arguments": "{\"query\": \"WITH cohort AS (\\n  SELECT order_id, order_status, order_purchase_timestamp,\\n         order_delivered_customer_date, order_estimated_delivery_date\\n  FROM orders\\n  WHERE order_purchase_timestamp >= '2017-01-01' AND order_purchase_timestamp < '2018-01-01'\\n), month_metrics AS (\\n  SELECT substr(order_purchase_timestamp,1,7) AS mois,\\n         AVG(CASE WHEN order_status='delivered' AND order_delivered_customer_date IS NOT NULL\\n                  THEN julianday(order_delivered_customer_date)-julianday(order_purchase_timestamp) END) AS delai_moyen,\\n         AVG(CASE WHEN order_status='delivered' AND order_delivered_customer_date IS NOT NULL\\n                  THEN julianday(order_delivered_customer_date)-julianday(order_estimated_delivery_date) END) AS ecart_moyen\\n  FROM cohort GROUP BY substr(order_purchase_timestamp,1,7)\\n), review_order AS (\\n  SELECT order_id, AVG(review_score) AS score FROM order_reviews GROUP BY order_id\\n), month_scores AS (\\n  SELECT substr(c.order_purchase_timestamp,1,7) AS mois, AVG(r.score) AS note_moyenne\\n  FROM cohort c JOIN review_order r ON r.order_id=c.order_id\\n  GROUP BY substr(c.order_purchase_timestamp,1,7)\\n)\\nSELECT 'd\u00e9lai_moyen_max' AS indicateur, mois AS periode, ROUND(delai_moyen,2) AS valeur FROM month_metrics ORDER BY delai_moyen DESC LIMIT 1\\nUNION ALL\\nSELECT 'd\u00e9lai_moyen_min', mois, ROUND(delai_moyen,2) FROM month_metrics ORDER BY delai_moyen ASC LIMIT 1\\nUNION ALL\\nSELECT 'note_moyenne_max', mois, ROUND(note_moyenne,2) FROM month_scores ORDER BY note_moyenne DESC LIMIT 1\\nUNION ALL\\nSELECT 'note_moyenne_min', mois, ROUND(note_moyenne,2) FROM month_scores ORDER BY note_moyenne ASC LIMIT 1\\nUNION ALL\\nSELECT '\u00e9cart_estimation_moyen_max', mois, ROUND(ecart_moyen,2) FROM month_metrics ORDER BY ecart_moyen DESC LIMIT 1\\nUNION ALL\\nSELECT '\u00e9cart_estimation_moyen_min', mois, ROUND(ecart_moyen,2) FROM month_metrics ORDER BY ecart_moyen ASC LIMIT 1\"}"
