          "arguments": "{\"query\":\"WITH cohort AS (\\n  SELECT order_id, order_status, order_purchase_timestamp, order_delivered_customer_date, order_estimated_delivery_date\\n  FROM orders WHERE order_purchase_timestamp >= '2017-01-01' AND order_purchase_timestamp < '2018-01-01'\\n), delivered AS (\\n  SELECT order_id, julianday(order_delivered_customer_date)-julianday(order_estimated_delivery_date) AS ecart_jours\\n  FROM cohort WHERE order_status='delivered' AND order_delivered_customer_date IS NOT NULL\\n), review_order AS (\\n  SELECT r.order_id, AVG(r.review_score) AS note_commande\\n  FROM order_reviews r JOIN cohort c ON c.order_id=r.order_id GROUP BY r.order_id\\n), delivery_stats AS (\\n  SELECT COUNT(*) AS livraisons_mesurables,\\n         SUM(CASE WHEN ecart_jours>0 THEN 1 ELSE 0 END) AS livraisons_apres_date_estimee,\\n         ROUND(100.0*SUM(CASE WHEN ecart_jours>0 THEN 1 ELSE 0 END)/COUNT(*),1) AS part_apres_date_estimee_pourcent\\n  FROM delivered\\n), review_stats AS (\\n  SELECT COUNT(*) AS commandes_avec_avis,\\n         SUM(CASE WHEN note_commande>=4 THEN 1 ELSE 0 END) AS commandes_note_au_moins_4,\\n         ROUND(100.0*SUM(CASE WHEN note_commande>=4 THEN 1 ELSE 0 END)/COUNT(*),1) AS part_note_au_moins_4_pourcent,\\n         SUM(CASE WHEN note_commande<=2 THEN 1 ELSE 0 END) AS commandes_note_au_plus_2,\\n         ROUND(100.0*SUM(CASE WHEN note_commande<=2 THEN 1 ELSE 0 END)/COUNT(*),1) AS part_note_au_plus_2_pourcent\\n  FROM review_order\\n)\\nSELECT '2017' AS periode, * FROM delivery_stats CROSS JOIN review_stats\"}",
